import { useEffect, useRef, useState } from 'react';
import manifest from '../../content/image-manifest.json';

const BASE = '/images/work';

/**
 * <picture> with AVIF + WebP srcsets generated by `npm run images`.
 * Fades in when loaded. Pass `priority` for the LCP image (eager + fetchpriority high).
 */
export default function ResponsiveImage({
  name,
  alt,
  sizes = '100vw',
  priority = false,
  className = '',
  imgClassName = '',
  style,
}) {
  const [loaded, setLoaded] = useState(false);
  const imgRef = useRef(null);
  // Cached images can finish before onLoad is attached — check on mount.
  useEffect(() => {
    if (imgRef.current?.complete) setLoaded(true);
  }, []);
  const meta = manifest[name];
  if (!meta) {
    if (import.meta.env.DEV) console.warn(`[ResponsiveImage] "${name}" not in image-manifest.json — run npm run images`);
    return null;
  }
  const srcset = (ext) => meta.widths.map((w) => `${BASE}/${name}-${w}.${ext} ${w}w`).join(', ');
  const largest = meta.widths[meta.widths.length - 1];

  return (
    <picture className={className}>
      <source type="image/avif" srcSet={srcset('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcset('webp')} sizes={sizes} />
      <img
        ref={imgRef}
        src={`${BASE}/${name}-${largest}.webp`}
        alt={alt}
        width={meta.width}
        height={meta.height}
        loading={priority ? 'eager' : 'lazy'}
        fetchpriority={priority ? 'high' : undefined}
        decoding="async"
        onLoad={() => setLoaded(true)}
        style={style}
        className={`transition-opacity duration-700 ${loaded ? 'opacity-100' : 'opacity-0'} ${imgClassName}`}
      />
    </picture>
  );
}
